"""12.79.17: synthetic orders (invented names) shaped like the user's 2025 orders: uppercase surname, visa signers,
4-digit points with dash lines, unit labels inside a numbered group, a unit label after the basis."""
import sys,os
from docx import Document
OUT=(sys.argv[1] if len(sys.argv)>1 else 'cases').rstrip('/')+'/';os.makedirs(OUT,exist_ok=True)
HEAD=lambda n,d:['ПРИКАЗ','КОМАНДИРА ВОЙСКОВОЙ ЧАСТИ 77777','по строевой части',f'« {d[:2]} » мая 2026 г. № {n}','г. Энск','']
SIGN=['','ВрИО КОМАНДИРА ВОЙСКОВОЙ ЧАСТИ 77777','гвардии подполковник','\tА.Энский','','ВрИО НАЧАЛЬНИКА ШТАБА ВОЙСКОВОЙ ЧАСТИ 77777','гвардии капитан','\tБ.Штабной','','старший лейтенант','\tВ.Визов','','лейтенант','\tГ.Исполнителев']
def save(n,d,body):
  doc=Document()
  for t in HEAD(n,d)+body+SIGN:doc.add_paragraph(t)
  doc.save(OUT+f'Приказ {n} от {d}.docx')
